const g = gate(r); if (g) return g;
if (!r.ok) return show(mode() + '-list', '⚠️ No pude leer tus datos: ' + detail(r));
const s = r.body.snapshot;
const lines = [
  '🏠 GTD — ¿qué quieres hacer?', '',
  '📥 Inbox: ' + s.inbox + '    ▶️ Acciones: ' + s.next,
  '⏳ Esperando: ' + s.waiting + '    🌱 Algún día: ' + s.someday,
];
if (s.stalled_projects) lines.push('🧩 Proyectos sin siguiente paso: ' + s.stalled_projects);
if (s.overdue) lines.push('⚠️ Vencidas: ' + s.overdue);
lines.push('', '✍️ Escríbeme cualquier cosa y la capturo al inbox.');
return show(mode() + '-menu', lines.join('\n'));

